 await page.locator(`.level-card[data-level="${i}"]`).click(); await page.locator('#startLevelButton').click();
 console.log('world:',await page.locator('#levelName').innerText(), 'expected:',name);
 await page.waitForTimeout(1000);
 await page.locator('#pauseButton').click(); await page.locator('#exitButton').click();
}
