(()=>{
 'use strict';
 const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=960,H=540,G=430,$=id=>document.getElementById(id);
 const ui={hud:$('hud'),level:$('levelName'),timer:$('timer'),best:$('bestTime'),beat:$('beatIndicator'),toast:$('toast')};
 const screens={title:$('titleScreen'),levels:$('levelScreen'),pause:$('pauseScreen'),result:$('resultScreen')};
 const areas=[{name:'VILA DOS TELHADOS',start:0,end:3000,beat:.62,sky:['#17233b','#754f62'],ground:'#32343d',accent:'#f2cf83',hill:'#252b3a'}, {name:'FLORESTA SUSSURRANTE',start:3000,end:6000,beat:.54,sky:['#122b2b','#54715c'],ground:'#263b32',accent:'#c9df8b',hill:'#1c332d'}, {name:'RUÍNAS DO ECO',start:6000,end:9000,beat:.48,sky:['#28213b','#a56e62'],ground:'#3a3440',accent:'#f2bd78',hill:'#302a3e'}];
 const pads=[{x:2100,temple:0,boss:2780},{x:5100,temple:1,boss:5780},{x:8100,temple:2,boss:8780}];
 const platforms=[];for(let i=0;i<30;i++){const x=280+i*286;platforms.push({x,y:G-92-(i%3)*39,w:100+(i%2)*30,h:14});}
 let mode='title',player,worldX=0,camera=0,area=0,elapsed=0,last=0,shake=0,toastUntil=0,items=[],enemies=[],audioCtx=null,soundOn=true,keys={},bosses=[0,0,0],temples=[0,0,0],melodies=0,shards=0,fragments=0,upgrades={heart:0,jump:0,claw:0},quests=[0,0,0],shop=false;
 const audioButton=$('soundToggle');
 function show(which){Object.values(screens).forEach(s=>s.hidden=true);if(which)screens[which].hidden=false;}
 function fmt(s){const m=Math.floor(s/60),sec=(s%60).toFixed(1).padStart(4,'0');return `${String(m).padStart(2,'0')}:${sec}`;}
 function toast(t){ui.toast.textContent=t;ui.toast.classList.add('show');toastUntil=performance.now()+2200;}
 function tone(freq,d=.08,w='sine',v=.02){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=w;o.frequency.value=freq;g.gain.setValueAtTime(v,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d);}catch(_){}}
 function save(){const data={x:Math.floor(worldX),hp:player.hp,melodies,shards,fragments,upgrades,bosses,temples,quests};localStorage.setItem('ritmo-rpg-save',JSON.stringify(data));toast('PROGRESSO SALVO NO MARCO');tone(660,.1,'triangle');}
 function load(){try{const d=JSON.parse(localStorage.getItem('ritmo-rpg-save')||'{}');worldX=d.x||0;melodies=d.melodies||0;shards=d.shards||0;fragments=d.fragments||0;upgrades=Object.assign(upgrades,d.upgrades||{});bosses=d.bosses||bosses;temples=d.temples||temples;quests=d.quests||quests;}catch(_){} }
 function startFromTitle(){load();mode='levels';show('levels');updateMapCards();}
 function updateMapCards(){document.querySelectorAll('.level-card').forEach((c,i)=>{const unlocked=i===0||bosses[i-1]>0;c.classList.toggle('locked',!unlocked);c.classList.toggle('selected',i===area);c.setAttribute('aria-disabled',String(!unlocked));});}
 function startGame(){mode='playing';load();area=worldX<3000?0:worldX<6000?1:2;player={x:190,y:G-48,w:34,h:43,vy:0,onGround:true,jumps:0,hp:3+upgrades.heart,face:1,attack:0,roll:0,invuln:0,climb:false,grabAt:0,hit:0,combo:0};elapsed=0;camera=Math.max(0,worldX-190);items=Array.from({length:44},(_,i)=>({x:180+i*202,y:G-73-(i%4)*22,kind:i%9===0?'fragment':'shard',got:false}));enemies=Array.from({length:23},(_,i)=>({x:510+i*390,home:510+i*390,y:G-33,hp:i%7===0?3:2,max:i%7===0?3:2,alive:true,boss:i%7===0,dir:1,hit:0}));ui.hud.hidden=false;ui.beat.hidden=false;$('controlsHint').hidden=false;$('mobileControls').hidden=false;show(null);syncHud();last=performance.now();tone(440,.1,'triangle');}
 function syncHud(){ui.level.textContent=areas[area].name;$('noteCount').textContent=String(player?.hp||0);$('comboCount').textContent=String(shards);ui.timer.textContent=fmt(elapsed);$('progressBar').style.width=`${Math.max(0,Math.min(100,worldX/9000*100))}%`;ui.best.textContent=`♫ ${melodies}/3 · FRAG. ${fragments%4}/4`;}
 function pause(){if(mode!=='playing')return;mode='pause';show('pause');}
 function resume(){if(mode!=='pause')return;mode='playing';show(null);last=performance.now();}
 function setSound(){soundOn=!soundOn;audioButton.classList.toggle('muted',!soundOn);audioButton.setAttribute('aria-label',soundOn?'Desativar som':'Ativar som');if(soundOn)tone(440);}
 function closeGame(){mode='levels';ui.hud.hidden=true;ui.beat.hidden=true;$('controlsHint').hidden=true;$('mobileControls').hidden=true;updateMapCards();show('levels');}
 function endGame(){mode='result';ui.hud.hidden=true;ui.beat.hidden=true;$('controlsHint').hidden=true;$('mobileControls').hidden=true;show('result');$('resultTime').textContent=fmt(elapsed);$('resultNotes').textContent=`${shards} ✦`;$('resultCombo').textContent=`${melodies}/3`;$('resultStamp').textContent='♫';$('resultTitle').textContent='A lenda continua';$('resultMessage').textContent='As três melodias despertaram. O mapa ainda guarda segredos.';tone(740,.2,'triangle');}
 function beatGood(){const b=areas[area].beat,p=(elapsed%b)/b;return p<.16||p>.84;}
 function jump(){if(mode!=='playing')return;const p=player;if(p.climb){p.climb=false;p.vy=-540;p.jumps=1;return;}if(p.onGround){p.vy=-500-upgrades.jump*45;p.onGround=false;p.jumps=1;tone(410,.07);return;}if(p.jumps===1){if(beatGood()){p.vy=-650-upgrades.jump*35;p.combo++;toast('PULO MUSICAL!');tone(880,.12,'triangle',.04);}else{p.vy=-320;p.combo=0;toast('FORA DO RITMO — PULO FRACO');tone(170,.1);}p.jumps=2;}}
 function attack(){if(mode!=='playing'||player.attack>0)return;player.attack=.25;tone(240+upgrades.claw*60,.07,'sawtooth',.025);const p=player;for(const e of enemies){if(!e.alive)continue;const ex=e.home-camera;if(Math.abs(ex-(p.x+p.face*40))<58&&Math.abs(e.y-p.y)<62){e.hp--;e.hit=.24;if(e.hp<=0){e.alive=false;shards+=e.boss?8:2;player.combo++;if(e.boss)bossDefeated(e.home);else if(area<3)quests[area]=Math.min(quests[area]+1,3);tone(690,.12,'triangle');}}}}
 function roll(){if(mode!=='playing'||player.roll>0)return;player.roll=.48;player.invuln=.52;tone(190,.08,'triangle');}
 function nearThing(x,r=70){return Math.abs(worldX-x)<r;}
 function interact(){if(mode!=='playing')return;const p=player;if(p.climb){p.climb=false;p.vy=-450;p.jumps=1;return;}
  for(let i=0;i<3;i++){const pt=pads[i];if(nearThing(pt.temple,100)){if(temples[i]){toast('TEMPLO CONCLUÍDO · CHEFE À ESPERA');return;}const weighted=Math.abs(worldX-(pt.temple-145))<75&&p.onGround;const held=performance.now()-p.grabAt<12000;if(!weighted||!held){toast(!weighted?'PISE NA PLACA DE PEDRA':'AGARRE A PAREDE E VOLTE À PLACA');return;}if(!beatGood()){toast('A PLACA RESPONDE À BATIDA... TENTE NO TEMPO!');tone(130,.1);return;}temples[i]=1;toast('TEMPLO RESOLVIDO · O SELO DO CHEFE SE QUEBROU');tone(780,.2,'triangle');save();return;}
   if(nearThing(pt.boss,115)){if(!temples[i]){toast('O GUARDIÃO ESTÁ PROTEGIDO · RESOLVA O TEMPLO');return;}if(bosses[i]){toast('GUARDIÃO DERROTADO · MELODIA APRENDIDA');return;}toast('GUARDIÃO: ATAQUE APÓS A INVESTIDA!');return;}}
  const npc=[430,3460,6460],merchant=[710,3750,6750],rest=[970,3970,6970];for(let i=0;i<3;i++){if(nearThing(npc[i],75)){quests[i]=Math.max(quests[i],1);toast(quests[i]>=3?'MISSÃO CONCLUÍDA · + 10 FRAGMENTOS!':'MISSÃO: DERROTE 3 CRIATURAS NESTA REGIÃO');if(quests[i]>=3){shards+=10;quests[i]=4;}return;}if(nearThing(merchant[i],78)){shop=!shop;toast(shop?'LOJA: [1] CORAÇÃO 12✦ · [2] PULO 10✦ · [3] GARRAS 10✦':'LOJA FECHADA');return;}if(nearThing(rest[i],70)){save();return;}}
  const gate=[3000,6000][area];if(gate&&nearThing(gate,100)){toast(melodies>=area+1?'PASSAGEM ABERTA':'PORTA SELADA · UMA MELODIA É NECESSÁRIA');return;}
  toast('EXPLORE: E FALA, ESCALA OU INTERAGE');}
 function buy(n){if(mode!=='playing'||!shop)return;const cost=n===1?12:10;if(shards<cost){toast('FALTAM FRAGMENTOS DE LUA');return;}if(n===1){upgrades.heart++;player.hp++;}if(n===2)upgrades.jump++;if(n===3)upgrades.claw++;shards-=cost;syncHud();toast(['','CORAÇÃO EXTRA EQUIPADO','PULO MAIS ALTO EQUIPADO','GARRAS REFORÇADAS'][n]);save();}
 function bossDefeated(x){const i=pads.findIndex(p=>Math.abs(p.boss-x)<20);if(i<0||bosses[i])return;bosses[i]=1;melodies=Math.max(melodies,i+1);shards+=18;toast(['MELODIA DO TELHADO DESBLOQUEADA','MELODIA DA FLORESTA DESBLOQUEADA','MELODIA DO ECO DESBLOQUEADA'][i]);if(i===2){setTimeout(()=>{if(mode==='playing')endGame();},700);}save();}
 function damage(){if(player.invuln>0)return;player.hp--;player.invuln=1.15;player.vy=-250;shake=.35;tone(120,.15,'square');if(player.hp<=0){player.hp=3+upgrades.heart;worldX=Math.floor(worldX/3000)*3000+120;camera=Math.max(0,worldX-190);toast('VOCÊ VOLTOU AO ÚLTIMO MARCO');}syncHud();}
 function update(dt,now){if(mode!=='playing')return;dt=Math.min(.04,dt);elapsed+=dt;const p=player,a=areas[area];if(p.attack>0)p.attack-=dt;if(p.roll>0)p.roll-=dt;if(p.invuln>0)p.invuln-=dt;if(shake>0)shake-=dt;
  const left=keys.ArrowLeft||keys.KeyA,right=keys.ArrowRight||keys.KeyD,up=keys.ArrowUp||keys.KeyW,down=keys.ArrowDown||keys.KeyS;let speed=p.roll>0?390:205;if(left){p.x-=speed*dt;p.face=-1;}if(right){p.x+=speed*dt;p.face=1;}if(p.x<120){p.x=120;if(worldX>0)worldX-=speed*dt;}if(p.x>W-180){worldX+=speed*dt;p.x=W-180;}worldX=Math.max(0,Math.min(9000,worldX));
  const wx=worldX+p.x;const climbable=[...Array.from({length:20},(_,i)=>600+i*450),...pads.map(v=>v.temple),...pads.map(v=>v.boss)];p.climb=false;if(keys.KeyE&&climbable.some(x=>Math.abs(x-wx)<57)&&!p.onGround){p.climb=true;p.vy=up?-180:down?180:0;p.grabAt=now;}if(p.climb){p.y+=p.vy*dt;}else{p.vy+=1250*dt;p.y+=p.vy*dt;}
