.card-description {
align-self:start;margin-top:2px}
.level-card .card-meta {
display:none}
.card-art small {
top:10px;right:10px}
.card-art:before {
height:55%}
.card-art:after {
height:68%}
.level-footer {
margin-top:11px}
.text-back {
font-size:8px}
.primary-button.compact {
