content.text:
:root {
--ink:#f7f5ee;--muted:#a3a6b0;--dim:#777d8a;--night:#10131c;--panel:#171b27;--line:rgba(255,255,255,.12);--lime:#d8fa70;--orange:#ff9367;--mono:'DM Mono',monospace;--sans:'Outfit',sans-serif}
* {
box-sizing:border-box}
html,body {
margin:0;min-height:100%;background:#0e1119;color:var(--ink);font-family:var(--sans)}
body {
min-height:100vh;display:flex;justify-content:center;align-items:center;padding:24px}
.shell {
width:min(1160px,100%)}
.topbar {
height:55px;display:flex;align-items:center;justify-content:space-between;padding:0 6px 15px}
.brand {
display:flex;align-items:center;gap:10px;text-decoration:none;color:#f6f4ee;font-size:13px;font-weight:800;letter-spacing:1.55px}
.brand-light {
font-weight:500;color:#9da1ad}
.brand-mark {
display:grid;place-items:center;width:27px;height:27px;color:#0f1414;background:var(--lime);font-size:19px;border-radius:8px}
.top-right {
display:flex;align-items:center;gap:11px;color:#9da2ae}
.live-dot {
height:6px;width:6px;background:var(--lime);border-radius:50%;box-shadow:0 0 11px #d8fa70}
.top-label,.sound-toggle,.footer,.controls-hint,.eyebrow,.title-stats,.level-card .card-meta,.level-hint,.hud-caption,.best-label,.notes-pill small,.combo-pill small,.level-chip,.pause-button {
font-family:var(--mono);letter-spacing:1px}
.top-label {
font-size:9px}
.sound-toggle {
border:1px solid var(--line);border-radius:6px;background:transparent;color:#e6e5df;padding:7px 10px;font-size:11px;cursor:pointer}
.sound-toggle span {
font-size:9px;color:#9da2ae}
.game-frame {
height:min(650px,calc(100vh - 127px));min-height:525px;position:relative;overflow:hidden;border:1px solid #343946;border-radius:12px;background:#1c2330;box-shadow:0 22px 80px #0006}
#game {
display:block;width:100%;height:100%;object-fit:cover}
.screen {
position:absolute;inset:0;z-index:2;background:linear-gradient(90deg,rgba(16,19,28,.98) 0%,rgba(16,19,28,.92) 36%,rgba(16,19,28,.11) 100%);display:flex;align-items:center;padding:7.3%}
.screen[hidden],.hud[hidden],.beat-indicator[hidden],.mobile-controls[hidden] {
display:none}
.title-copy {
width:53%;max-width:510px;position:relative;z-index:1}
.eyebrow {
display:flex;align-items:center;gap:10px;color:var(--lime);font-size:9px;letter-spacing:1.6px}
.eyebrow-line {
height:1px;width:24px;background:var(--lime)}
h1,h2,p {
margin:0}
.title-copy h1 {
font-size:clamp(42px,5.4vw,70px);line-height:.98;letter-spacing:-2.7px;font-weight:600;margin:22px 0 17px}
.title-copy h1 em,.level-heading h2 em {
font-weight:500;color:var(--lime);font-style:normal}
.title-copy p,.level-heading p {
max-width:365px;color:#a6a9b3;font-size:14px;line-height:1.7}
.title-actions {
display:flex;align-items:center;gap:21px;margin-top:27px}
.primary-button {
display:flex;align-items:center;gap:27px;justify-content:space-between;padding:0 18px;height:48px;min-width:170px;border:0;border-radius:6px;background:var(--lime);color:#171a1c;font:700 10px var(--mono);letter-spacing:.8px;cursor:pointer;transition:transform .18s,filter .18s}
.primary-button:hover {
transform:translateY(-2px);filter:brightness(1.05)}
.primary-button b {
font-size:16px}
.quiet-button,.text-back {
border:0;background:transparent;color:#c1c2c6;font:500 9px var(--mono);letter-spacing:1px;cursor:pointer;padding:12px 0}
.quiet-button:hover,.text-back:hover {
color:var(--lime)}
.quiet-button span {
color:var(--lime);font-size:15px;margin-left:8px}
.title-stats {
display:flex;align-items:center;gap:15px;margin-top:45px;color:#818694;font-size:8px}
.title-stats b {
color:#f3f1e9;font-size:13px;font-weight:500;margin-right:4px}
.title-stats i {
height:14px;width:1px;background:#444956}
.hero-cat {
position:absolute;right:3.5%;top:0;width:54%;height:100%;overflow:hidden;background:radial-gradient(ellipse at 60% 51%,#354356 0%,#283443 28%,#1d2735 52%,#141925 76%);clip-path:polygon(15% 0,100% 0,100% 100%,0 100%)}
.hero-glow {
position:absolute;width:420px;height:300px;right:7%;top:17%;background:radial-gradient(ellipse,#d2b68625,transparent 70%)}
.hero-moon {
position:absolute;top:14%;right:22%;width:88px;height:88px;background:#d8d1b3;border-radius:50%;opacity:.9;box-shadow:0 0 55px #ddd6b54d}
.hero-moon:after {
content:'';position:absolute;left:15px;top:-8px;width:83px;height:84px;border-radius:50%;background:#283443}
.hero-cat-art {
position:absolute;bottom:17%;left:44%;width:205px;height:240px;filter:drop-shadow(0 8px 18px #090b10aa);transform:rotate(-7deg)}
.cat-body {
position:absolute;width:102px;height:133px;left:53px;top:74px;border-radius:51% 47% 40% 42%;background:linear-gradient(120deg,#25262c,#080a0e 60%);transform:rotate(22deg)}
.cat-body:after {
content:'';position:absolute;width:35px;height:15px;border-radius:50%;background:#090a0d;right:-13px;top:106px;box-shadow:-66px 11px 0 -2px #111217}
.cat-head {
position:absolute;left:71px;top:35px;width:86px;height:78px;border-radius:46% 48% 42% 42%;background:linear-gradient(135deg,#31323a,#080a0d 68%);z-index:2}
.ear {
position:absolute;top:-21px;width:0;height:0;border-left:15px solid transparent;border-right:15px solid transparent;border-bottom:36px solid #15171c}
.ear.left {
left:2px;transform:rotate(-13deg)}
.ear.right {
right:1px;transform:rotate(14deg)}
.ear:after {
content:'';position:absolute;left:-7px;top:13px;border-left:7px solid transparent;border-right:7px solid transparent;border-bottom:17px solid #a4777b}
.eye {
position:absolute;top:32px;width:10px;height:13px;background:#e6cb57;border-radius:65% 35% 60% 40%;box-shadow:0 0 13px #ecd45a}
.eye.left {
left:20px}
.eye.right {
right:20px}
.cat-head:after {
content:'';position:absolute;top:52px;left:40px;width:5px;height:4px;background:#d890a0;clip-path:polygon(50% 100%,0 0,100% 0)}
.whisker {
position:absolute;width:23px;height:1px;background:#99959a;top:53px}
.w1 {
left:-12px;transform:rotate(-10deg)}
.w2 {
right:-12px;transform:rotate(10deg)}
.cat-tail {
position:absolute;z-index:0;left:25px;top:140px;width:105px;height:50px;border:16px solid #0a0c11;border-right-color:transparent;border-bottom-color:transparent;border-radius:65% 50% 0 50%;transform:rotate(-18deg)}
.cat-leg {
position:absolute;z-index:3;top:175px;width:20px;height:54px;border-radius:0 0 12px 12px;background:#111319}
.leg1 {
left:72px;transform:rotate(13deg)}
.leg2 {
left:121px;transform:rotate(-7deg)}
.hero-note {
position:absolute;color:var(--lime);font-size:23px;text-shadow:0 0 15px #d8fa7080}
.note-a {
top:32%;left:25%;transform:rotate(-15deg)}
.note-b {
top:54%;right:13%;font-size:31px;transform:rotate(11deg)}
.hero-stars {
position:absolute;right:10%;top:23%;font-size:13px;line-height:3.3;color:#b8c5cb7a}
.hero-caption {
position:absolute;bottom:8%;left:22%;display:flex;align-items:center;gap:11px;font:9px var(--mono);letter-spacing:1.4px;color:#b3b5b8}
.hero-caption i {
height:1px;width:30px;background:var(--lime)}
.hud {
position:absolute;z-index:1;left:0;right:0;top:0;height:70px;padding:17px 22px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,#0f141de8,#0f141d00)}
.hud-left {
width:31%;max-width:285px}
.level-chip {
font-size:9px;color:#f0f0eb;letter-spacing:1px}
.level-icon {
color:var(--lime);margin-right:7px}
.progress-track {
height:3px;margin-top:9px;background:#ffffff31;border-radius:4px;overflow:hidden}
.progress-track i {
display:block;width:0;height:100%;background:var(--lime);box-shadow:0 0 8px var(--lime);transition:width .15s}
.hud-center {
display:flex;flex-direction:column;align-items:center;gap:2px}
.hud-caption {
font-size:8px;color:#b1b5be}
.hud-center strong {
font:500 17px var(--mono);letter-spacing:1px}
.best-label {
font-size:7px;color:#9aa0a9;letter-spacing:.7px}
.hud-right {
display:flex;align-items:center;gap:14px}
.notes-pill,.combo-pill {
display:grid;grid-template-columns:16px 25px;align-items:center;column-gap:3px}
.notes-pill>span {
color:var(--lime);font-size:15px;grid-row:span 2}
.notes-pill strong,.combo-pill strong {
font:500 13px var(--mono)}
.notes-pill small,.combo-pill small {
font-size:7px;color:#aeb2bc;grid-column:2;letter-spacing:.5px}
.combo-flame {
grid-row:span 2;color:var(--orange);font-size:15px}
.pause-button {
width:29px;height:29px;border:1px solid #ffffff53;border-radius:50%;background:#11151b88;color:#fff;font-size:12px;cursor:pointer}
.beat-indicator {
position:absolute;z-index:2;top:79px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:7px;color:#fff;font:8px var(--mono);letter-spacing:1.3px}
.beat-ring {
height:9px;width:9px;border-radius:50%;background:var(--lime);box-shadow:0 0 12px var(--lime);animation:pulse .5s ease-in-out infinite alternate}
.beat-indicator.strong .beat-ring {
background:#ff9367;box-shadow:0 0 17px #ff9367}
