/* RPG polish: clear progression states and dependable touch targets. */
button:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
.game-frame{isolation:isolate;touch-action:pan-y}
#game{touch-action:none}
.level-card.locked{opacity:.52;filter:saturate(.55);cursor:not-allowed}
.level-card.locked:after{content:'🔒 REGIÃO SELADA';position:absolute;inset:auto 10px 10px auto;padding:5px 7px;border-radius:3px;background:#10131cdd;color:#e5dcae;font:7px var(--mono);letter-spacing:.7px}
.level-card.locked:hover{transform:none;border-color:#393e4b}
.level-card[aria-disabled=true]{cursor:not-allowed}
