  function attack(){if(mode!=='playing'||player.attack>0)return;player.attack=.25;tone(240+upgrades.claw*60,.07,'sawtooth',.025);for(const e of enemies){if(!e.alive)continue;const ex=e.home-camera;if(Math.abs(ex-(player.x+player.face*40))<58&&Math.abs(e.y-player.y)<62&&(!e.boss||e.vulnerable)){e.hp--;e.hit=.24;if(e.hp<=0){e.alive=false;shards+=e.boss?10:2;player.combo++;if(e.boss)bossDefeated(e.home);else quests[area]=Math.min(3,quests[area]+1);tone(690,.12,'triangle');}}}}
  function roll(){if(mode!=='playing'||player.roll>0)return;player.roll=.48;player.invuln=.52;tone(190,.08,'triangle');}
