  function save(showToast=true){const d={x:Math.floor(worldX+(player?.x||190)),hp:player?.hp||3,melodies,shards,fragments,upgrades,bosses,temples,quests};localStorage.setItem('ritmo-rpg-save',JSON.stringify(d));if(showToast){toast('PROGRESSO SALVO NO MARCO');tone(660,.1,'triangle');}}
  function load(){try{const d=JSON.parse(localStorage.getItem('ritmo-rpg-save')||'{}');worldX=Math.max(0,(d.x||0)-190);melodies=d.melodies||0;shards=d.shards||0;fragments=d.fragments||0;upgrades=Object.assign(upgrades,d.upgrades||{});bosses=d.bosses||bosses;temples=d.temples||temples;quests=d.quests||quests;}catch(_){}}
  function updateMapCards(){document.querySelectorAll('.level-card').forEach((c,i)=>{const unlocked=i===0||bosses[i-1]>0;c.classList.toggle('locked',!unlocked);c.classList.toggle('selected',i===area);c.setAttribute('aria-disabled',String(!unlocked));});}
  function startFromTitle(){load();mode='levels';mapSelection=null;const position=worldX+190;area=position<3000?0:position<6000?1:2;show('levels');updateMapCards();}
- function startGame(fromMap=false){mode='playing';if(fromMap&&mapSelection!==null){worldX=areas[area].start;}else{load();const position=worldX+190;area=position<3000?0:position<6000?1:2;}mapSelection=null;player={x:190,y:G-48,w:34,h:43,vy:0,onGround:true,jumps:0,hp:3+upgrades.heart,face:1,attack:0,roll:0,invuln:0,climb:false,grabAt:0,combo:0};elapsed=0;camera=Math.max(0,worldX-190);items=Array.from({length:44},(_,i)=>({x:180+i*202,y:G-73-(i%4)*22,kind:i%9===0?'fragment':'shard',got:false}));enemies=Array.from({length:23},(_,i)=>{const boss=i%7===0&&i<21,home=boss?pads[Math.floor(i/7)].boss:510+i*390;return{x:home,home,y:G-33,hp:boss?7:2,max:boss?7:2,alive:true,boss,hit:0};});ui.hud.hidden=false;ui.beat.hidden=false;$('controlsHint').hidden=false;$('mobileControls').hidden=false;show(null);syncHud();last=performance.now();tone(440,.1,'triangle');}
+ function startGame(fromMap=false){mode='playing';if(fromMap&&mapSelection!==null){worldX=areas[area].start;}else{load();const position=worldX+190;area=position<3000?0:position<6000?1:2;}mapSelection=null;player={x:190,y:G-48,w:34,h:43,vy:0,onGround:true,jumps:0,hp:3+upgrades.heart,face:1,attack:0,roll:0,invuln:0,climb:false,grabAt:0,combo:0};elapsed=0;camera=worldX;items=Array.from({length:44},(_,i)=>({x:180+i*202,y:G-73-(i%4)*22,kind:i%9===0?'fragment':'shard',got:false}));enemies=Array.from({length:23},(_,i)=>{const boss=i%7===0&&i<21,home=boss?pads[Math.floor(i/7)].boss:510+i*390;return{x:home,home,y:G-33,hp:boss?7:2,max:boss?7:2,alive:true,boss,hit:0};});ui.hud.hidden=false;ui.beat.hidden=false;$('controlsHint').hidden=false;$('mobileControls').hidden=false;show(null);syncHud();last=performance.now();tone(440,.1,'triangle');}
  function syncHud(){ui.level.textContent=areas[area].name;$('noteCount').textContent=String(player?.hp||0);$('comboCount').textContent=String(shards);ui.timer.textContent=fmt(elapsed);$('progressBar').style.width=`${Math.max(0,Math.min(100,worldX/9000*100))}%`;ui.best.textContent=`♫ ${melodies}/3 · FRAG. ${fragments%4}/4`;}
  function pause(){if(mode!=='playing')return;mode='pause';show('pause');}function resume(){if(mode!=='pause')return;mode='playing';show(null);last=performance.now();}
  function setSound(){soundOn=!soundOn;audioButton.classList.toggle('muted',!soundOn);audioButton.setAttribute('aria-label',soundOn?'Desativar som':'Ativar som');if(soundOn)tone(440);}
  function closeGame(){mode='levels';ui.hud.hidden=true;ui.beat.hidden=true;$('controlsHint').hidden=true;$('mobileControls').hidden=true;updateMapCards();show('levels');}
